$cats=['Identity Proof','Educational Certificate','Address Proof','Reference Document'];
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();$action=$_POST['action']??'';
  if($action==='register'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)throw new RuntimeException('Enter a valid name and email, and use a password of at least 10 characters.');$q=db()->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");try{$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);}catch(PDOException $e){if($e->getCode()==='23000')throw new RuntimeException('That email is already registered.');throw $e;}$id=(int)db()->lastInsertId();$ref='VD-'.strtoupper(bin2hex(random_bytes(3)));db()->prepare('INSERT INTO applications(user_id,reference_no) VALUES(?,?)')->execute([$id,$ref]);$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'candidate'];session_regenerate_id(true);audit('candidate_registered',null,'Candidate registration');flash('Welcome to VeriDesk. Your application is ready.');go('?page=dashboard');}
  if($action==='login'){$email=strtolower(trim($_POST['email']??''));$q=db()->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();$portal=$_POST['portal']??'all';if(!$u||!password_verify($_POST['password']??'',$u['password_hash'])||($portal==='admin'&&$u['role']!=='admin')||($portal==='candidate'&&$u['role']!=='candidate')){audit('login_failed',null,'Failed sign-in attempt');throw new RuntimeException('Email or password was not recognized for this portal.');}session_regenerate_id(true);$_SESSION['user']=array_intersect_key($u,array_flip(['id','name','email','role']));audit('login',null,'Successful sign-in');go('?page='.($u['role']==='admin'?'admin':'dashboard'));}
  if($action==='logout'){audit('logout');$_SESSION=[];session_destroy();go('?page=home');}
  if($action==='submit_application'){require_role('candidate');$a=current_application();if(!$a)throw new RuntimeException('Application not found.');db()->prepare("UPDATE applications SET status='Submitted',submitted_at=COALESCE(submitted_at,NOW()) WHERE id=?")->execute([$a['id']]);$admins=db()->query("SELECT id FROM users WHERE role='admin'")->fetchAll();foreach($admins as $ad)notify((int)$ad['id'],'New application submitted',user()['name'].' submitted '.$a['reference_no'].'.',(int)$a['id']);notify((int)user()['id'],'Application submitted','Your application '.$a['reference_no'].' was submitted for manual review.',(int)$a['id']);audit('application_submitted',(int)$a['id'],'Application submitted');flash('Application submitted for manual review.');go('?page=application');}
  if($action==='upload'){require_role('candidate');$a=current_application();$cat=$_POST['category']??'';if(!$a||!in_array($cat,$cats,true))throw new RuntimeException('Choose a valid document category.');if(empty($_FILES['document'])||$_FILES['document']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a file up to 8 MB and try again.');$f=$_FILES['document'];if($f['size']>8*1024*1024||$f['size']<1)throw new RuntimeException('The maximum file size is 8 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];if(!isset($allowed[$ext])||$allowed[$ext]!==$mime)throw new RuntimeException('Upload a valid PDF, JPG or PNG file.');$dir=$config['app']['upload_dir'];if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Private upload storage is not available.');$stored=bin2hex(random_bytes(24)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('The file could not be stored.');$old=db()->prepare('SELECT stored_name FROM documents WHERE application_id=? AND category=?');$old->execute([$a['id'],$cat]);$oldName=$old->fetchColumn();if($oldName){db()->prepare("UPDATE documents SET original_name=?,stored_name=?,mime_type=?,file_size=?,status='Pending',admin_remarks=NULL,uploaded_at=NOW(),reviewed_at=NULL WHERE application_id=? AND category=?")->execute([basename($f['name']),$stored,$mime,$f['size'],$a['id'],$cat]);if(is_file($dir.'/'.$oldName))unlink($dir.'/'.$oldName);audit('document_replaced',(int)$a['id'],$cat.' replaced');}else{db()->prepare('INSERT INTO documents(application_id,category,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?,?)')->execute([$a['id'],$cat,basename($f['name']),$stored,$mime,$f['size']]);audit('document_uploaded',(int)$a['id'],$cat.' uploaded');}db()->prepare("UPDATE applications SET status='Under Review' WHERE id=?")->execute([$a['id']]);flash('Document uploaded securely.');go('?page=documents');}
  if($action==='review'){require_role('admin');$id=(int)($_POST['document_id']??0);$status=$_POST['status']??'';$remark=trim($_POST['remarks']??'');if(!in_array($status,['Pending','Approved','Rejected','Resubmission Required'],true))throw new RuntimeException('Invalid review status.');if(in_array($status,['Rejected','Resubmission Required'],true)&&$remark==='')throw new RuntimeException('A reason is required when rejecting or requesting resubmission.');$q=db()->prepare('SELECT d.*,a.user_id,a.id aid,a.reference_no FROM documents d JOIN applications a ON a.id=d.application_id WHERE d.id=?');$q->execute([$id]);$d=$q->fetch();if(!$d)throw new RuntimeException('Document not found.');db()->prepare('UPDATE documents SET status=?,admin_remarks=?,reviewed_at=NOW() WHERE id=?')->execute([$status,$remark?:null,$id]);$appStatus=sync_application((int)$d['aid']);notify((int)$d['user_id'],'Document '.$status,$d['category'].': '.($remark?:'Your document was reviewed.').' Application status: '.$appStatus.'.',(int)$d['aid']);if($appStatus==='Completed')notify((int)$d['user_id'],'Application completed','All required documents have been approved.',(int)$d['aid']);audit('document_reviewed',(int)$id,$d['category'].' marked '.$status.($remark?': '.$remark:''));flash('Document review saved.');go('?page=application&id='.$d['aid']);}
  if($action==='read_notification'){if(!user())go('?page=login');$q=db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?');$q->execute([(int)$_POST['id'],user()['id']]);go('?page=notifications');}
 } else {
  if($page==='file'){if(!user())go('?page=login');$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT d.*,a.user_id FROM documents d JOIN applications a ON a.id=d.application_id WHERE d.id=?');$q->execute([$id]);$d=$q->fetch();if(!$d||(user()['role']!=='admin'&&(int)$d['user_id']!==(int)user()['id'])){http_response_code(404);exit('File not found.');}$path=$config['app']['upload_dir'].'/'.$d['stored_name'];if(!is_file($path)){http_response_code(404);exit('No uploaded file is available for this demonstration record.');}header('Content-Type: '.$d['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: '.(!empty($_GET['download'])?'attachment':'inline').'; filename="'.rawurlencode($d['original_name']).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;}
  if(in_array($page,['application','documents','dashboard','profile','status'],true))require_role('candidate');
  if($page==='notifications'&&!user())go('?page=login');
  if(in_array($page,['admin','applications','activity','admin_application'],true))require_role('admin');
 }
