function badge(string $s):string{$c=match($s){'Completed','Approved'=>'green','Action Required','Rejected','Resubmission Required'=>'red','Under Review','Pending'=>'amber',default=>'slate'};return '<span class="badge '.$c.'">'.e($s).'</span>';}
