ss="doc-icon">▤</div><div class="doc-info"><b><?=e($cat)?></b><small><?=$d?e($d['original_name']):'Not uploaded yet'?></small></div><?=$d?badge($d['status']):'<span class="badge slate">Needed</span>'?></div><?php }?></section>
