anel-head"><h2>Recently submitted applications</h2><a href="?page=applications">All applications →</a></div><?php table_apps($rows);?></section>
<?php elseif($page==='applications'):$search=trim($_GET['q']??'');$status=$_GET['status']??'';$sql='SELECT a.*,u.name,u.email FROM applications a JOIN users u ON u.id=a.user_id WHERE (u.name LIKE ? OR a.reference_no LIKE ?)';$args=['%'.$search.'%','%'.$search.'%'];if(in_array($status,['Not Submitted','Submitted','Under Review','Action Required','Completed'],true)){$sql.=' AND a.status=?';$args[]=$status;}$sql.=' ORDER BY a.created_at DESC';$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();?><div class="page-head"><div><div class="eyebrow">ADMINISTRATION</div><h1>Applications</h1><p>Search candidates and review submitted documents.</p></div></div><form class="filters"><input type="hidden" name="page" value="applications"><input name="q" placeholder="Name or reference number" value="<?=e($search)?>"><select name="status"><option value="">All statuses</option><?php foreach(['Not Submitted','Submitted','Under Review','Action Required','Completed'] as $s):?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn secondary">Filter</button></form><section class="panel"><?php table_apps($rows);?></section><?php
elseif($page==='admin_application'):$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT a.*,u.name,u.email FROM applications a JOIN users u ON u.id=a.user_id WHERE a.id=?');$q->execute([$id]);$record=$q->fetch();if(!$record):?><div class="alert danger">Application not found.</div><?php else:$q=db()->prepare('SELECT * FROM documents WHERE application_id=? ORDER BY id');$q->execute([$id]);?><div class="page-head"><div><div class="eyebrow">APPLICATION · <?=e($record['reference_no'])?></div><h1><?=e($record['name'])?></h1><p><?=e($record['email'])?> · <?=e($record['reference_no'])?></p></div><?=badge($record['status'])?></div><section class="panel"><div class="panel-head"><h2>Candidate submission</h2><span class="muted">Submitted <?=e($record['submitted_at']?date('M j, Y',strtotime($record['submitted_at'])):'Not submitted')?></span></div><?php foreach($q->fetchAll() as $d):?><div class="document-card"><div class="doc-row"><div class="doc-icon">▤</div><div class="doc-info"><b><?=e($d['category'])?></b><small><?=e($d['original_name'])?> · <?=number_format((int)$d['file_size']/1024)?> KB · <?=date('M j, Y',strtotime($d['uploaded_at']))?></small></div><?=badge($d['status'])?></div><div class="doc-actions"><a class="btn secondary small" href="?page=file&amp;id=<?=$d['id']?>">View</a><a class="btn secondary small" href="?page=file&amp;id=<?=$d['id']?>&amp;download=1">Download</a></div><?php if($d['file_size']>0):?><form method="post" class="review-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review"><input type="hidden" name="document_id" value="<?=$d['id']?>"><select name="status"><?php foreach(['Pending','Approved','Rejected','Resubmission Required'] as $s):?><option <?=$d['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><input name="remarks" value="<?=e($d['admin_remarks'])?>" placeholder="Required reason for rejection or resubmission"><button class="btn primary small">Save review</button></form><?php else:?><p class="muted demo-note">This seeded entry is review metadata only; no sample document file is included.</p><?php endif;?></div><?php endforeach;?></section><?php endif;?>
elseif($page==='activity'):$q=db()->query('SELECT l.*,u.name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 300');?><div class="page-head"><div><div class="eyebrow">ADMINISTRATION</div><h1>Activity log</h1><p>Recent security and workflow events.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Event</th><th>User</th><th>Description</th><th>Time</th></tr></thead><tbody><?php foreach($q->fetchAll() as $r):?><tr><td><?=e($r['action'])?></td><td><?=e($r['name']??'System')?></td><td><?=e($r['description'])?></td><td><?=e(date('M j, Y g:i A',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:?><section class="panel"><h1>Page unavailable</h1><p>This page is unavailable for the current account.</p><a href="?page=<?=user()&&user()['role']==='admin'?'admin':'home'?>">Return to overview</a></section><?php endif;layout_end();
function table_apps(array $rows):void{?><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Reference</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['email'])?></small></td><td><?=e($r['reference_no'])?></td><td><?=e($r['submitted_at']?date('M j, Y',strtotime($r['submitted_at'])):'—')?></td><td><?=badge($r['status'])?></td><td><a href="?page=admin_application&id=<?=$r['id']?>">Review →</a></td></tr><?php endforeach;?></tbody></table></div><?php }
